CREATE TABLE tk_schema (id INTEGER PRIMARY KEY CHECK (id=1), schema_version INTEGER NOT NULL, state VARCHAR(16) NOT NULL);
INSERT INTO tk_schema VALUES (1,1,'INITIALIZING');
CREATE TABLE tk_owner (id VARCHAR(400) PRIMARY KEY, zone_id VARCHAR(100) NOT NULL, version BIGINT NOT NULL CHECK(version>=0), revision BIGINT NOT NULL CHECK(revision>=0), cursor_secret VARCHAR(64) NOT NULL);
CREATE TABLE tk_resource (owner_id VARCHAR(400) NOT NULL, entity_type VARCHAR(16) NOT NULL, id UUID NOT NULL, version BIGINT NOT NULL CHECK(version>=0), payload TEXT NOT NULL, PRIMARY KEY(owner_id,entity_type,id), FOREIGN KEY(owner_id) REFERENCES tk_owner(id));
CREATE TABLE tk_relation (owner_id VARCHAR(400) NOT NULL, from_type VARCHAR(16) NOT NULL, from_id UUID NOT NULL, kind VARCHAR(16) NOT NULL, to_type VARCHAR(16) NOT NULL, to_id UUID NOT NULL, PRIMARY KEY(owner_id,from_type,from_id,kind,to_type,to_id), FOREIGN KEY(owner_id,from_type,from_id) REFERENCES tk_resource(owner_id,entity_type,id), FOREIGN KEY(owner_id,to_type,to_id) REFERENCES tk_resource(owner_id,entity_type,id));
CREATE TABLE tk_external_reference (owner_id VARCHAR(400) NOT NULL, provider_id VARCHAR(400) NOT NULL, repository_id VARCHAR(8192) NOT NULL, external_id VARCHAR(2000) NOT NULL, entity_type VARCHAR(16) NOT NULL CHECK(entity_type='TASK'), task_id UUID NOT NULL, reference_key VARCHAR(64) NOT NULL, PRIMARY KEY(owner_id,reference_key), FOREIGN KEY(owner_id,entity_type,task_id) REFERENCES tk_resource(owner_id,entity_type,id));
CREATE TABLE tk_active (owner_id VARCHAR(400) PRIMARY KEY, entity_type VARCHAR(16) NOT NULL CHECK(entity_type='ACTIVITY'), activity_id UUID NOT NULL, FOREIGN KEY(owner_id,entity_type,activity_id) REFERENCES tk_resource(owner_id,entity_type,id));
CREATE TABLE tk_receipt (owner_id VARCHAR(400) NOT NULL, command_id UUID NOT NULL, fingerprint VARCHAR(64) NOT NULL, status INTEGER NOT NULL, body TEXT NOT NULL, etag VARCHAR(200), location VARCHAR(4096), created_at VARCHAR(40) NOT NULL, PRIMARY KEY(owner_id,command_id), FOREIGN KEY(owner_id) REFERENCES tk_owner(id));
CREATE TABLE tk_change (owner_id VARCHAR(400) NOT NULL, sequence BIGINT NOT NULL, entity_type VARCHAR(16) NOT NULL, entity_id VARCHAR(400) NOT NULL, change_type VARCHAR(16) NOT NULL, occurred_at VARCHAR(40) NOT NULL, PRIMARY KEY(owner_id,sequence), FOREIGN KEY(owner_id) REFERENCES tk_owner(id));
